long long area12[1005];

void _do(vector<int> &lst){
    if (lst.size() <= 1)
        return;

    long long best = 0;
    for(auto v: lst){
        area12[v] = get_area(1, 2, v);
        if (area12[v] > area12[best])
            best = v;
    }

    vector <int> l, r;
    for(auto v: lst){
        if (v == best)
            continue;

        if (get_sign(1, best, v) == 1)
            l.push_back(v);
        else
            r.push_back(v);
    }

    sort(l.begin(), l.end(), [&](int x,int y){
        return area12[x] > area12[y];
    });
    sort(r.begin(), r.end(), [&](int x,int y){
